42	export class ToolRegistry {
43	  private readonly tools = new Map<string, StoredTool>();
44	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
45	  private readonly ajv = new Ajv({validateFormats: false} as any);
46	  private readonly schemaValidators = new WeakMap<object, ReturnType<InstanceType<typeof Ajv>['compile']>>();
47	
48	  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
49	    return typeof source === 'function' ? source() : source;
50	  }
51	
52	  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
53	    const resolved = this.resolveDefinition(definition);
54	    let staticValidator: ReturnType<InstanceType<typeof Ajv>['compile']> | undefined;
55	
56	    if (typeof definition !== 'function') {
57	      try {
58	        staticValidator = this.ajv.compile(resolved.inputSchema);
59	      } catch (e) {
60	        throw new Error(`Failed to compile schema for tool "${resolved.name}": ${(e as Error).message}`, {
61	          cause: e,
62	        });
63	      }
64	    }
65	
66	    this.tools.set(resolved.name, {definitionSource: definition, execute, staticValidator});
67	  }
68	
69	  get(name: string): RegisteredTool | undefined {
70	    const tool = this.tools.get(name);
71	    if (!tool) return undefined;
72	    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
73	  }
74	
75	  getDefinitions(): ToolDefinition[] {
76	    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
77	  }
78	
79	  getPromptInstructions(): string[] {
80	    return this.getDefinitions()
81	      .filter(t => t.promptInstructions)
82	      .map(t => `${t.name}: ${t.promptInstructions}`);
83	  }
84	
85	  getExamplePrompts(): string[] {
86	    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
87	  }
88	
89	  has(name: string): boolean {
90	    return this.tools.has(name);
91	  }
92	
93	  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
94	    const tool = this.tools.get(name);
95	    if (!tool) {
96	      log.warn('tool', 'tool not found', {name});
97	      throw new Error(`Unknown tool: ${name}`);
98	    }
99	
100	    const resolved = this.resolveDefinition(tool.definitionSource);
101	    const validator = tool.staticValidator ?? this.getOrCompileValidator(name, resolved.inputSchema);
102	
103	    if (!validator) return {result: 'Validator compilation failed'};
104	
105	    const valid = validator(input);
106	    if (!valid) {
107	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
108	      const errors = (validator.errors as any[]) ?? [];
109	      const errorMessages = errors
110	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
111	        .map((error: any) => {
112	          const path = error.instancePath || error.dataPath || '/';
113	          return this.formatValidationError(error, path);
114	        })
115	        .join('; ');
116	      log.info('tool', 'validation failed', {name, errorCount: errors.length});
117	      return {result: `Validation failed: ${errorMessages}`};
118	    }
119	
120	    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
121	    const rawResult = await tool.execute(input, context);
122	    const response = normalizeToolResponse(rawResult);
123	    log.info('tool', 'execution complete', {
124	      name,
125	      rawType: typeof rawResult,
126	      clientMessageCount: response.clientMessages?.length ?? 0,
127	      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
128	      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
129	    });
130	    return response;
131	  }
132	
133	  private getOrCompileValidator(name: string, schema: unknown): ReturnType<InstanceType<typeof Ajv>['compile']> | null {
134	    const schemaObj = schema as object;
135	    if (this.schemaValidators.has(schemaObj)) {
136	      return this.schemaValidators.get(schemaObj)!;
137	    }
138	    try {
139	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
140	      const compiled = this.ajv.compile(schema as any);
141	      this.schemaValidators.set(schemaObj, compiled);
142	      return compiled;
143	    } catch (e) {
144	      log.error('tool', 'schema compilation failed', {name, error: (e as Error).message});
145	      return null;
146	    }
147	  }
148	
149	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
150	  private formatValidationError(error: any, path: string): string {
151	    switch (error.keyword) {
152	      case 'required':
153	        return `required property '${error.params.missingProperty}' is missing`;
154	      case 'type':
155	        return `property '${path || '/'}' must be of type ${error.params.type}`;
156	      default:
157	        return `property '${path || '/'}' failed ${error.keyword} constraint`;
158	    }
159	  }
